<script setup lang="ts">
import {computed,ref} from 'vue';
import {useAppSession} from '../session-context.ts';
import {hexToXY,same} from '../engine.ts';
import type {HistoricalRegion} from '../../shared/history.ts';
import {Button} from './ui/button';
import {AlertDialog,AlertDialogContent,AlertDialogTitle,AlertDialogDescription} from './ui/alert-dialog';
const {historical,historicalDefinition,historicalNotice,historicalProgress,historicalMenu,startHistorical,setHistoricalConvoy,busy,game,mapView,previews}=useAppSession();
const restart=ref(false),expanded=ref(false);
const outcome=computed(()=>historical.value?.result);
const carrierExits=computed(()=>{
 const exits=historicalDefinition.value?.regions.filter(r=>r.kind==='exit')??[];
 return previews.value.filter(p=>p.ship.cfg.carrier&&exits.some(r=>r.cells.some(cell=>same(cell,p.nodes.at(-1)!.pos))))
  .map(p=>({id:p.ship.id,label:p.ship.label,airborne:game.value?.planes.filter(plane=>plane.mother===p.ship.id&&plane.hp>0).length??0,launching:p.plan.planes.length}));
});
const stage=computed(()=>({contact:'发现目标',engage:'牵制交战',pursuit:historical.value?.scenarioId==='midway'?'追击或撤离':'保持追踪',retreat:'保持追踪',advance:'打开航道',control:'控制港口',breakout:'突破拦截',breakthrough:'突破拦截','last-carrier':'营救最后一艘航母',search:'搜索敌舰',strike:'组织空袭',counterattack:'应对反击',withdraw:'掩护撤离',escort:'护航撤退'}[historical.value?.stage??'']??historical.value?.stage));
const focus=(region:HistoricalRegion)=>{const cell=region.cells[Math.floor(region.cells.length/2)];if(cell)mapView.value?.focus(hexToXY(cell));};
const restartBattle=()=>{restart.value=false;if(historical.value)startHistorical(historical.value.scenarioId,false);};
</script>
<template>
<section v-if="historical&&historicalDefinition" class="historical-mission" :class="{resolved:outcome}" data-historical-mission>
 <div class="mission-heading"><div><p class="eyebrow">历史战斗 · {{historicalDefinition.date}}</p><h2>{{historicalDefinition.title}} <span>{{historicalDefinition.subtitle}}</span></h2><p v-if="!outcome" class="mission-stage">{{stage}} · 剩余 {{Math.max(0,historicalDefinition.roundLimit-(game?.round??1)+1)}} 回合</p></div><div class="mission-actions"><Button variant="outline" :disabled="busy" @click="historicalMenu">战斗列表</Button><Button variant="outline" :disabled="busy" @click="restart=true">重试本场</Button><Button variant="ghost" :aria-expanded="expanded" @click="expanded=!expanded">{{expanded?'收起简报':'任务与史实'}}</Button></div></div>
 <div v-if="!outcome" class="mission-progress" aria-live="polite"><div v-for="objective in historicalProgress" :key="objective.id" :class="{complete:objective.complete}"><span>{{objective.complete?'✓':'○'}} {{objective.label}}</span><b>{{objective.current}} / {{objective.target}}</b></div></div>
 <div v-if="!outcome&&!busy&&carrierExits.length" class="extraction-preview" data-extraction-preview><p v-for="carrier in carrierExits" :key="carrier.id">{{carrier.label}} 计划停入撤离区：当前在航 {{carrier.airborne}} 架，本轮计划起飞 {{carrier.launching}} 架。若回合末存活并留在区内，仍在场的舰载机将随队撤离，不再参与后续攻击；本轮已完成的攻击保留。</p></div>
 <div v-if="outcome" class="historical-result" role="status" data-historical-result><strong>{{outcome.won?'任务完成':'任务未完成'}} <span :aria-label="outcome.stars+' 星'">{{'★'.repeat(outcome.stars)}}{{'☆'.repeat(3-outcome.stars)}}</span></strong><p>{{outcome.reason}} · 第 {{outcome.round}} 回合</p><p v-for="(label,index) in historicalDefinition.bonusObjectives" :key="label">{{outcome.bonus[index]?'✓':'○'}} {{label}}</p><p>已撤离：{{Object.values(historical.extracted).filter(s=>s.team===0).map(s=>s.label).join('、')||'无'}}。留场存活：{{game?.ships.filter(s=>s.team===0&&s.hp>0).map(s=>s.label).join('、')||'无'}}。</p><details><summary>历史经过</summary><p>{{historicalDefinition.history}}</p></details></div>
 <div class="mission-regions"><span>海图标记</span><Button v-for="region in historicalDefinition.regions" :key="region.id" variant="ghost" size="sm" :data-region-kind="region.kind" @click="focus(region)">{{region.label}} · 定位</Button></div>
 <div v-if="historical.scenarioId==='samar'&&!outcome" class="convoy-controls"><strong>航母组</strong><Button variant="outline" :disabled="busy" :aria-pressed="historical.convoyRoute==='central'" @click="setHistoricalConvoy('central',historical.convoyWait)">中央航线</Button><Button variant="outline" :disabled="busy" :aria-pressed="historical.convoyRoute==='east'" @click="setHistoricalConvoy('east',historical.convoyWait)">东侧绕行</Button><Button variant="outline" :disabled="busy||historical.convoyWaitLastRound===(game?.round??1)-1" :aria-pressed="historical.convoyWait" @click="setHistoricalConvoy(historical.convoyRoute,!historical.convoyWait)">{{historical.convoyWait?'取消等待':'等待一轮'}}</Button><small>航母路径已在海图预览，不可连续两轮等待。</small></div>
 <div v-if="expanded" class="mission-brief"><ul><li v-for="goal in historicalDefinition.objectives" :key="goal">{{goal}}</li><li v-for="goal in historicalDefinition.bonusObjectives" :key="goal">额外一星：{{goal}}</li></ul><p>{{historicalDefinition.history}}</p><p>每场独立保存；本场阶段间保留耐久、弹药与位置。</p><a v-for="source in historicalDefinition.sources" :key="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title}} ↗</a></div>
 <p v-if="historicalNotice.includes('失败')" role="alert" class="mission-error">{{historicalNotice}}</p>
 <AlertDialog :open="restart" @update:open="restart=$event"><AlertDialogContent><AlertDialogTitle>重试当前历史战斗？</AlertDialogTitle><AlertDialogDescription>本场舰队恢复初始配置，替换当前进度。最佳战果及其他战斗存档保留。</AlertDialogDescription><div class="mission-actions"><Button variant="outline" @click="restart=false">取消</Button><Button @click="restartBattle">确认重试</Button></div></AlertDialogContent></AlertDialog>
</section>
</template>
<style scoped>
.historical-mission{margin:14px 0 8px;padding:16px 20px;background:linear-gradient(100deg,#142b3d,var(--ink-1));border:1px solid var(--line-2);border-left:3px solid var(--brass);border-radius:var(--radius-lg)}.mission-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.mission-heading h2{font-size:19px;letter-spacing:.03em;margin:4px 0}.mission-heading h2 span{font-size:14px;color:var(--brass-hi);margin-left:10px}.mission-stage{font-size:12px;color:var(--text-2)}.mission-actions,.mission-regions,.convoy-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.mission-actions button{font-size:12px}.mission-progress{display:flex;flex-wrap:wrap;gap:8px 20px;margin-top:12px}.mission-progress>div{display:flex;gap:16px;align-items:center;font-size:13px;color:var(--text-2)}.mission-progress .complete{color:var(--signal)}.mission-progress b{color:var(--brass-hi);font:13px var(--font-code)}.mission-regions{margin-top:8px;font-size:11px;color:var(--text-3)}.mission-regions button{font-size:11px;height:30px}.mission-regions [data-region-kind=exit]{color:var(--signal)}.mission-regions [data-region-kind=enemy-exit]{color:#e4a395}.convoy-controls{padding-top:10px;margin-top:8px;border-top:1px solid var(--line-1);font-size:12px}.convoy-controls button{min-height:36px;font-size:12px}.convoy-controls [aria-pressed=true]{color:var(--signal);border-color:var(--signal)}.convoy-controls small{color:var(--text-3)}.mission-brief,.historical-result{font-size:13px;color:var(--text-2);line-height:1.8;margin-top:10px}.mission-brief ul{list-style:disc;padding-left:20px}.mission-brief a{display:inline-block;margin-right:18px;color:var(--signal)}.historical-result>strong{font-size:20px;color:var(--text-1)}.historical-result>strong span{color:var(--brass-hi);margin-left:12px}.extraction-preview{margin-top:10px;padding:8px 12px;border-left:2px solid var(--brass);background:var(--ink-1);font-size:12px;color:var(--brass-hi);line-height:1.7}.mission-error{color:#f2a69c;font-size:12px}.historical-result summary{cursor:pointer;color:var(--brass-hi)}
@media(max-width:700px){.historical-mission{padding:12px;margin:8px 0}.mission-heading{display:block}.mission-heading h2 span{display:block;margin:4px 0}.mission-actions{margin-top:10px}.mission-progress{gap:8px}.mission-progress>div{flex:1 1 100%;justify-content:space-between}.convoy-controls small{flex-basis:100%}}
</style>
